"""Static progress dashboard, regenerated by the agent tracker after every status change.

v1 (lead, Phase 0): agent workload board, weighted overall completion, rough ETA,
recent lifecycle events, and a first experiment-status summary read from
``logs/experiment_events.jsonl``. A5 (observability engineer) extends this with
the learning visuals and richer experiment sections.

Output: ``artifacts/dashboard/progress.html`` - self-contained HTML (inline CSS,
no external assets, no server), auto-refreshing every REFRESH_SECONDS. Every
number shown is read from the logs named in the page footer; nothing is
hard-coded.
"""
from __future__ import annotations

import html
from datetime import datetime, timezone
from pathlib import Path

from src.utils import ARTIFACTS_DIR, LOGS_DIR, atomic_write_text, parse_ts, read_json, read_jsonl, rel, utc_now

DASHBOARD_PATH = ARTIFACTS_DIR / "dashboard" / "progress.html"
STATUS_PATH = LOGS_DIR / "agent_status.json"
EVENTS_PATH = LOGS_DIR / "agent_events.jsonl"
EXPERIMENT_EVENTS_PATH = LOGS_DIR / "experiment_events.jsonl"
REFRESH_SECONDS = 30
RECENT_EVENTS = 25

STATUS_ORDER = ("queued", "running", "blocked", "review", "done", "failed")
STATUS_GLYPH = {"queued": "○", "running": "◐", "blocked": "■", "review": "◆", "done": "●", "failed": "✕"}

CSS = """
:root { --bg:#f7f7f5; --card:#ffffff; --ink:#1f2328; --ink2:#57606a; --muted:#8b949e; --line:#e4e6ea;
        --track:#e9ebee; --fill:#3b6ea5; --good:#2f7d4f; --warn:#b26a00; --bad:#b3261e; --info:#3b6ea5; }
* { box-sizing:border-box; }
body { margin:0; background:var(--bg); color:var(--ink); font:14px/1.45 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif; }
main { max-width:1180px; margin:0 auto; padding:24px 20px 48px; }
h1 { font-size:20px; margin:0 0 4px; font-weight:650; }
h2 { font-size:15px; margin:28px 0 10px; font-weight:650; color:var(--ink); }
.sub { color:var(--ink2); font-size:13px; }
.card { background:var(--card); border:1px solid var(--line); border-radius:8px; padding:16px 18px; }
.grid { display:grid; gap:12px; }
.tiles { grid-template-columns:repeat(auto-fit,minmax(120px,1fr)); }
.tile { background:var(--card); border:1px solid var(--line); border-radius:8px; padding:12px 14px; }
.tile .k { color:var(--ink2); font-size:12px; text-transform:uppercase; letter-spacing:.04em; }
.tile .v { font-size:24px; font-weight:650; margin-top:2px; font-variant-numeric:tabular-nums; }
.hero { display:flex; gap:28px; align-items:flex-start; flex-wrap:wrap; }
.hero .big { font-size:44px; font-weight:700; line-height:1; font-variant-numeric:tabular-nums; }
.bar { height:8px; background:var(--track); border-radius:4px; overflow:hidden; min-width:120px; }
.bar .fill { height:100%; background:var(--fill); border-radius:4px; }
table { width:100%; border-collapse:collapse; font-size:13px; }
th { text-align:left; color:var(--ink2); font-weight:600; border-bottom:1px solid var(--line); padding:8px 8px; white-space:nowrap; }
td { border-bottom:1px solid var(--line); padding:8px 8px; vertical-align:top; }
tr:last-child td { border-bottom:none; }
td.num, th.num { text-align:right; font-variant-numeric:tabular-nums; white-space:nowrap; }
.mono { font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:12px; }
.muted { color:var(--muted); }
.st { white-space:nowrap; font-weight:600; }
.st-running { color:var(--info); } .st-blocked { color:var(--warn); } .st-failed { color:var(--bad); }
.st-done { color:var(--good); } .st-review { color:var(--ink); } .st-queued { color:var(--muted); }
.warn { color:var(--warn); }
.wrap { overflow-x:auto; }
footer { margin-top:32px; color:var(--muted); font-size:12px; }
code { font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:12px; background:#f0f1f3; padding:1px 4px; border-radius:3px; }
"""


def _e(value: object) -> str:
    return html.escape("" if value is None else str(value))


def _fmt_elapsed(start: str | None, end: str | None) -> str:
    if not start:
        return "—"
    end_dt = parse_ts(end) if end else datetime.now(timezone.utc)
    secs = max(int((end_dt - parse_ts(start)).total_seconds()), 0)
    hours, rem = divmod(secs, 3600)
    mins, s = divmod(rem, 60)
    if hours:
        return f"{hours}h {mins:02d}m"
    return f"{mins}m {s:02d}s" if mins else f"{s}s"


def _bar(pct: float, label: str = "") -> str:
    pct = max(0.0, min(100.0, float(pct or 0.0)))
    return (
        f'<div class="bar" role="progressbar" aria-valuenow="{pct:.0f}" aria-valuemin="0" aria-valuemax="100" '
        f'title="{_e(label)}"><div class="fill" style="width:{pct:.1f}%"></div></div>'
    )


def _status_cell(status: str) -> str:
    return f'<span class="st st-{_e(status)}">{STATUS_GLYPH.get(status, "?")} {_e(status)}</span>'


# --------------------------------------------------------------------------- sections


def _overall_section(status: dict) -> str:
    o = status.get("overall") or {}
    total = o.get("total_work_units", 0) or 0
    completed = o.get("completed_work_units", 0) or 0
    blocked = o.get("blocked_work_units", 0) or 0
    pct = o.get("percent_complete", 0) or 0
    gates = status.get("acceptance_gates_passed", False)
    eta_note = "Rough ETA = remaining weighted units x median observed seconds per completed unit; not a commitment."
    if o.get("eta_uncertain_due_to_blocked"):
        eta_note += " Blocked work makes this estimate more uncertain."
    return f"""
<div class="card hero">
  <div>
    <div class="sub">Overall completion (weighted work units)</div>
    <div class="big">{pct:g}%</div>
    <div style="margin-top:8px;width:320px">{_bar(pct, f"{completed:g} of {total:g} units")}</div>
    <div class="sub" style="margin-top:6px">{completed:g} of {total:g} units complete
      &middot; {blocked:g} units blocked
      &middot; acceptance gates: <strong>{"passed" if gates else "not yet passed"}</strong>
      {"" if gates else "(100% is reserved until they pass)"}</div>
  </div>
  <div>
    <div class="sub">ETA</div>
    <div style="font-size:18px;font-weight:650;margin-top:6px">{_e(o.get("eta_label", "ETA unavailable"))}</div>
    <div class="sub" style="margin-top:6px">computed {_e(o.get("eta_computed_at", "—"))}
      &middot; median {_e(o.get("median_seconds_per_unit") if o.get("median_seconds_per_unit") is not None else "—")} s/unit
      over {_e(o.get("completed_unit_count", 0))} completed units</div>
    <div class="sub muted" style="margin-top:4px;max-width:420px">{eta_note}</div>
  </div>
</div>"""


def _counts_section(status: dict) -> str:
    counts = (status.get("overall") or {}).get("counts") or {}
    tiles = [("configured", counts.get("configured", len(status.get("agents", []))))]
    tiles += [(s, counts.get(s, 0)) for s in STATUS_ORDER]
    cells = "".join(
        f'<div class="tile"><div class="k">{STATUS_GLYPH.get(k, "")} {_e(k)}</div><div class="v">{_e(v)}</div></div>'
        for k, v in tiles
    )
    return f'<div class="grid tiles">{cells}</div>'


def _agents_section(status: dict) -> str:
    agents = status.get("agents", [])
    if not agents:
        return '<div class="card muted">No agents registered yet.</div>'
    rows = []
    for a in agents:
        blockers = ", ".join(a.get("blocked_by") or []) or "—"
        units = f"{a.get('completed_work_units', 0):g}/{a.get('total_work_units', 0):g}"
        rows.append(
            "<tr>"
            f"<td class='mono'>{_e(a.get('agent_id'))}</td>"
            f"<td>{_e(a.get('role'))}</td>"
            f"<td>{_status_cell(a.get('status', 'queued'))}</td>"
            f"<td>{_e(a.get('current_task') or '—')}</td>"
            f"<td class='mono'>{_e(a.get('last_artifact') or '—')}</td>"
            f"<td class='num'>{_e(_fmt_elapsed(a.get('started_at'), a.get('finished_at')))}</td>"
            f"<td>{_bar(a.get('percent_complete', 0), units)}<div class='sub' style='margin-top:3px'>{units} units &middot; {a.get('percent_complete', 0):g}%</div></td>"
            f"<td>{_e(a.get('eta_label'))}</td>"
            f"<td>{_e(blockers)}</td>"
            f"<td class='sub'>{_e(a.get('note') or '')}</td>"
            "</tr>"
        )
    return f"""
<div class="card wrap"><table>
<thead><tr><th>Agent</th><th>Role</th><th>Status</th><th>Current work</th><th>Latest artifact</th>
<th class="num">Elapsed</th><th>Progress</th><th>ETA</th><th>Blocked by</th><th>Note</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table></div>"""


def _blocked_section(status: dict) -> str:
    blocked = [a for a in status.get("agents", []) if a.get("status") == "blocked"]
    if not blocked:
        return '<div class="card muted">No blocked work.</div>'
    items = "".join(
        f"<li><span class='mono'>{_e(a['agent_id'])}</span> blocked by "
        f"<span class='mono'>{_e(', '.join(a.get('blocked_by') or []) or 'unspecified')}</span>"
        f" &mdash; {_e(a.get('note') or a.get('current_task') or '')}"
        f" ({max(a.get('total_work_units', 0) - a.get('completed_work_units', 0), 0):g} units remaining)</li>"
        for a in blocked
    )
    return f'<div class="card"><ul style="margin:0;padding-left:18px">{items}</ul></div>'


def _experiment_section() -> str:
    try:
        records = read_jsonl(EXPERIMENT_EVENTS_PATH)
    except ValueError as exc:
        return f'<div class="card warn">experiment_events.jsonl could not be parsed: {_e(exc)}</div>'
    if not records:
        return (
            '<div class="card muted">No experiment runs yet. This section fills from '
            "<code>logs/experiment_events.jsonl</code> once baseline / reflection-only / skill-learning conditions run.</div>"
        )
    # Keep the latest attempt per (run, condition, task); aggregate per (run, condition).
    latest: dict[tuple, dict] = {}
    for r in records:
        key = (r.get("run_id"), r.get("condition"), r.get("task_id"))
        if key not in latest or (r.get("attempt") or 0) >= (latest[key].get("attempt") or 0):
            latest[key] = r
    groups: dict[tuple, dict] = {}
    for (run_id, condition, _task), r in latest.items():
        g = groups.setdefault(
            (run_id, condition),
            {"tasks": 0, "done": 0, "attempts": 0, "errors": 0, "scores": [], "provider": r.get("provider_mode"),
             "model": r.get("model_identifier"), "last": r.get("timestamp") or ""},
        )
        g["tasks"] += 1
        g["done"] += 1 if r.get("status") == "done" else 0
        g["attempts"] += int(r.get("execution_attempts") or r.get("attempt") or 1)
        g["errors"] += int(r.get("execution_errors") or 0)
        if r.get("evaluator_score_total") is not None:
            g["scores"].append(float(r["evaluator_score_total"]))
        g["last"] = max(g["last"], r.get("timestamp") or "")
    rows = []
    for (run_id, condition), g in sorted(groups.items(), key=lambda kv: (str(kv[0][0]), str(kv[0][1]))):
        mean = f"{sum(g['scores']) / len(g['scores']):.2f}" if g["scores"] else "—"
        rows.append(
            "<tr>"
            f"<td class='mono'>{_e(run_id)}</td><td>{_e(condition)}</td>"
            f"<td class='num'>{g['done']}/{g['tasks']}</td><td class='num'>{mean}</td>"
            f"<td class='num'>{g['attempts']}</td><td class='num'>{g['errors']}</td>"
            f"<td class='mono'>{_e(g['provider'])} / {_e(g['model'])}</td><td class='mono'>{_e(g['last'])}</td>"
            "</tr>"
        )
    return f"""
<div class="card wrap"><table>
<thead><tr><th>Run</th><th>Condition</th><th class="num">Tasks done</th><th class="num">Mean rubric score (0&ndash;4)</th>
<th class="num">Attempts</th><th class="num">Exec. errors</th><th>Provider / model</th><th>Last event</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table>
<div class="sub" style="margin-top:8px">Latest attempt per task; source <code>logs/experiment_events.jsonl</code>.
Results from <code>manual_or_stub</code> runs are deterministic simulations, not LLM results.</div></div>"""


def _events_section() -> str:
    try:
        events = read_jsonl(EVENTS_PATH)
    except ValueError as exc:
        return f'<div class="card warn">agent_events.jsonl could not be parsed: {_e(exc)}</div>'
    if not events:
        return '<div class="card muted">No events yet.</div>'
    rows = []
    for ev in reversed(events[-RECENT_EVENTS:]):
        detail = ev.get("artifact") or ev.get("note") or ev.get("task") or ""
        rows.append(
            "<tr>"
            f"<td class='mono'>{_e(ev.get('timestamp'))}</td><td class='mono'>{_e(ev.get('agent_id'))}</td>"
            f"<td>{_e(ev.get('event'))}</td><td>{_status_cell(ev.get('status', '')) if ev.get('status') else ''}</td>"
            f"<td>{_e(ev.get('current_task') or '')}</td><td class='sub'>{_e(detail)}</td>"
            "</tr>"
        )
    return f"""
<div class="card wrap"><table>
<thead><tr><th>Time (UTC)</th><th>Agent</th><th>Event</th><th>Status</th><th>Task</th><th>Detail</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table></div>"""


# --------------------------------------------------------------------------- render


def build_html(status: dict) -> str:
    generated = utc_now()
    return f"""<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta http-equiv="refresh" content="{REFRESH_SECONDS}">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>claims-skill-loop &middot; progress</title>
<style>{CSS}</style></head>
<body><main>
<h1>claims-skill-loop &mdash; build &amp; experiment progress</h1>
<div class="sub">Generated {_e(generated)} &middot; auto-refreshes every {REFRESH_SECONDS} s &middot; tracker updated {_e(status.get("updated_at"))}</div>

<h2>Overall completion</h2>
{_overall_section(status)}

<h2>Agent workload</h2>
{_counts_section(status)}
<div style="height:12px"></div>
{_agents_section(status)}

<h2>Blocked work</h2>
{_blocked_section(status)}

<h2>Experiment status</h2>
{_experiment_section()}

<h2>Recent agent events</h2>
{_events_section()}

<footer>Sources: <code>{_e(rel(STATUS_PATH))}</code>, <code>{_e(rel(EVENTS_PATH))}</code>, <code>{_e(rel(EXPERIMENT_EVENTS_PATH))}</code>.
Educational demonstration on synthetic healthcare claims data; nothing here is medical, actuarial, or operational evidence.</footer>
</main></body></html>
"""


def render(out_path: Path | str | None = None) -> Path:
    status = read_json(STATUS_PATH, default=None) or {"agents": [], "overall": {}, "updated_at": None}
    target = Path(out_path) if out_path else DASHBOARD_PATH
    return atomic_write_text(target, build_html(status))


def main() -> int:
    path = render()
    print(f"dashboard written: {rel(path)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
